window.VF1_UNITS = {"9":{"unit":9,"code":"VF1-U09","title":"Working & Earning","startNumber":212,"endNumber":245,"entries":[{"number":212,"term":"ambition · ambitious","sourceTerm":"ambition (n) · ambitious (a)","spoken":"ambition · ambitious","ipa":"/æˈmbɪʃən æˈmbɪʃəs/","type":"noun · adjective","meaning":"tham vọng · có tham vọng","definition":"A strong desire to achieve something; determined to succeed.","note":"","example":"Mai's ambition is to become a doctor, and she is ambitious enough to study every day."},{"number":213,"term":"apply for a job/scholarship · application form · application process","sourceTerm":"apply (v) for a job/scholarship · application form · application process","spoken":"apply for a job or scholarship · application form · application process","ipa":"/əˈplaɪ fɔːr ə dʒɑːb ɔːr ˈskɑːlɚˌʃɪp ˌæpləˈkeɪʃən fɔːrm ˌæpləˈkeɪʃən ˈprɑːˌsɛs/","type":"verb","meaning":"nộp đơn xin việc/học bổng · mẫu đơn · quá trình nộp đơn","definition":"To formally request a job or scholarship; a request form; the stages of applying.","note":"","example":"Lan applied for a scholarship by completing the application form; the application process took one week."},{"number":214,"term":"career · pursue a career","sourceTerm":"career (n) · pursue (v) a career","spoken":"career · pursue a career","ipa":"/kɚˈɪr pɚˈsuː ə kɚˈɪr/","type":"verb · noun","meaning":"sự nghiệp · theo đuổi sự nghiệp","definition":"A long-term profession; to work towards a chosen profession.","note":"","example":"Nam wants to pursue a career in engineering."},{"number":215,"term":"colleague ~ co-worker","sourceTerm":"colleague (n) ~ co-worker (n)","spoken":"colleague ~ co-worker","ipa":"/ˈkɑːliɡ koʊ ˈwɝːkɚ/","type":"noun","meaning":"đồng nghiệp","definition":"A person you work with.","note":"colleague thường dùng trong môi trường nghề nghiệp; co-worker là bất kì người nào làm cùng nơi.","example":"My colleague, or co-worker, helped me on my first day."},{"number":216,"term":"contract","sourceTerm":"contract (n)","spoken":"contract","ipa":"/ˈkɑːˌntrækt/","type":"noun","meaning":"bản hợp đồng","definition":"A legal written agreement.","note":"","example":"Read the contract carefully before you sign it."},{"number":217,"term":"department # apartment","sourceTerm":"department (n) # apartment (n)","spoken":"department # apartment","ipa":"/dɪˈpɑːrtmənt əˈpɑːrtmənt/","type":"noun","meaning":"phòng/ban trong tổ chức # căn hộ","definition":"A section of an organization; not the same as apartment.","note":"department nghĩa là phòng/ban trong tổ chức; apartment nghĩa là căn hộ. Hai từ gần giống về chữ và âm nhưng nghĩa hoàn toàn khác.","example":"Lan works in the sales department and lives in an apartment near the office."},{"number":218,"term":"deserve st / to do st","sourceTerm":"deserve (v) st / to do st","spoken":"deserve something or to do something","ipa":"/dɪˈzɝːv ˈsʌmθɪŋ ɔːr tuː duː ˈsʌmθɪŋ/","type":"verb","meaning":"xứng đáng","definition":"To be worthy of something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: deserve (v) st / to do st","example":"Students who work hard deserve praise."},{"number":219,"term":"earn · earn money · earn a living","sourceTerm":"earn (v) · earn money · earn a living","spoken":"earn · earn money · earn a living","ipa":"/ɝːn ɝːn ˈmʌni ɝːn ə ˈlɪvɪŋ/","type":"verb","meaning":"kiếm được · kiếm tiền · kiếm sống","definition":"To receive money for work; to support yourself financially.","note":"","example":"Mai earns money by teaching, and this job helps her earn a living."},{"number":220,"term":"goal · pursue a goal · reach/achieve a goal","sourceTerm":"goal (n) · pursue a goal · reach/achieve a goal","spoken":"goal · pursue a goal · reach or achieve a goal","ipa":"/ɡoʊl pɚˈsuː ə ɡoʊl riːtʃ ɔːr əˈtʃiːv ə ɡoʊl/","type":"noun","meaning":"mục tiêu · theo đuổi mục tiêu · đạt mục tiêu","definition":"An aim; to work towards or reach an aim.","note":"","example":"Lan set a goal, pursued the goal every day, and finally achieved it."},{"number":221,"term":"manage · manager","sourceTerm":"manage (v) · manager (n)","spoken":"manage · manager","ipa":"/ˈmænədʒ ˈmænədʒɚ/","type":"verb · noun","meaning":"quản lí · người quản lí","definition":"To control work or people; a person who manages.","note":"","example":"The manager manages the team and checks each task."},{"number":222,"term":"profession · professional","sourceTerm":"profession (n) · professional (a)","spoken":"profession · professional","ipa":"/prəˈfɛʃən prəˈfɛʃənəl/","type":"noun · adjective","meaning":"nghề chuyên môn · chuyên nghiệp/thuộc nghề chuyên môn","definition":"A job requiring specialist training; skilled and appropriate for work.","note":"","example":"Teaching is a profession, and teachers should act in a professional way."},{"number":223,"term":"impress · impressive · impression · make an impression on sb/st","sourceTerm":"impress (v) · impressive (a) · impression (n) · make an impression on sb/st","spoken":"impress · impressive · impression · make an impression on somebody or something","ipa":"/ˌɪˈmprɛs ˌɪˈmprɛsɪv ˌɪˈmprɛʃən meɪk æn ˌɪˈmprɛʃən ɑːn ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ/","type":"verb · noun · adjective","meaning":"gây ấn tượng · gây ấn tượng mạnh · ấn tượng · tạo ấn tượng với ai/điều gì","definition":"To make someone admire or notice; causing admiration; an effect on someone's opinion.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: impress (v) · impressive (a) · impression (n) · make an impression on sb/st","example":"Her clear talk impressed the class; it was impressive and made a strong impression on us."},{"number":224,"term":"income # salary # wage # pension","sourceTerm":"income (n) # salary (n) # wage (n) # pension (n)","spoken":"income # salary # wage # pension","ipa":"/ˈɪˌnkʌm ˈsælɚi weɪdʒ ˈpɛnʃən/","type":"noun","meaning":"thu nhập # lương cố định theo tháng/năm # tiền công theo giờ/tuần # lương hưu","definition":"Money received from any source; fixed regular pay; pay based on hours or days; retirement pay.","note":"income là toàn bộ thu nhập; salary là lương cố định; wage thường tính theo giờ/ngày; pension là lương hưu.","example":"Her income includes a monthly salary, while hourly workers receive a wage and retired workers receive a pension."},{"number":225,"term":"pressure ~ stress · under pressure","sourceTerm":"pressure (n) ~ stress (n) · under pressure","spoken":"pressure ~ stress · under pressure","ipa":"/ˈprɛʃɚ strɛs ˈʌndɚ ˈprɛʃɚ/","type":"noun","meaning":"sức ép hoặc trạng thái căng thẳng · đang chịu áp lực","definition":"Stress caused by demands; in a stressful situation.","note":"pressure thường là yêu cầu/sức ép từ bên ngoài; stress là trạng thái căng thẳng bên trong. under pressure nghĩa là chịu sức ép.","example":"Students often feel stress and work under pressure before an exam."},{"number":226,"term":"retire · retirement","sourceTerm":"retire (v) · retirement (n)","spoken":"retire · retirement","ipa":"/rɪˈtaɪr riˈtaɪɚmənt/","type":"verb · noun","meaning":"nghỉ hưu · sự/thời gian nghỉ hưu","definition":"To stop working permanently; the period after work ends.","note":"","example":"My grandfather retired at sixty, and he enjoys his retirement."},{"number":227,"term":"staff","sourceTerm":"staff (n)","spoken":"staff","ipa":"/stæf/","type":"noun","meaning":"toàn thể nhân viên; đội ngũ nhân sự","definition":"All the people employed by an organization.","note":"","example":"The school staff includes all teachers, office workers, and technical assistants."},{"number":228,"term":"strike · on strike","sourceTerm":"strike (v,n) · on strike","spoken":"strike · on strike","ipa":"/straɪk ɑːn straɪk/","type":"verb · noun","meaning":"đình công/cuộc đình công · đang đình công","definition":"To stop working as a protest; a period of work stoppage.","note":"","example":"The workers went on strike, so the factory stopped for a day."},{"number":229,"term":"tax","sourceTerm":"tax (v,n)","spoken":"tax","ipa":"/tæks/","type":"verb · noun","meaning":"đánh thuế / thuế","definition":"To charge money for government purposes; money charged by government.","note":"","example":"Workers pay income tax, and the government taxes higher incomes."},{"number":230,"term":"wealth · wealthy ~ rich","sourceTerm":"wealth (n) · wealthy (a) ~ rich (a)","spoken":"wealth · wealthy ~ rich","ipa":"/wɛlθ ˈwɛlθi rɪtʃ/","type":"noun · adjective","meaning":"sự giàu có/tài sản · giàu có","definition":"A large amount of money or valuable property; rich.","note":"rich là từ thông dụng; wealthy trang trọng hơn và thường gợi nhiều tài sản lâu dài; wealth là danh từ.","example":"Wealth can make a family wealthy or rich, but it does not always bring happiness."},{"number":231,"term":"be fed up with st","sourceTerm":"be fed up with st","spoken":"be fed up with something","ipa":"/biː fɛd ʌp wɪð ˈsʌmθɪŋ/","type":"phrase / pattern","meaning":"chán ngấy cái gì","definition":"Very bored or annoyed with something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: be fed up with st","example":"The team was fed up with repeated delays."},{"number":232,"term":"duty · on duty >< off duty","sourceTerm":"duty (n) · on duty >< off duty","spoken":"duty · on duty >< off duty","ipa":"/ˈduːti ɑːn ˈduːti ɔːf ˈduːti/","type":"noun","meaning":"nhiệm vụ/trách nhiệm · đang trực/làm nhiệm vụ >< đã nghỉ trực","definition":"A responsibility; working at an assigned time; not currently working.","note":"duty nghĩa là nhiệm vụ/trách nhiệm; on duty nghĩa là đang trực/làm nhiệm vụ; off duty nghĩa là đã nghỉ trực.","example":"The nurse was on duty at night and went off duty at eight; caring for patients was her duty."},{"number":233,"term":"in charge of st ~ responsible for st","sourceTerm":"in charge of st ~ responsible for st","spoken":"in charge of something ~ responsible for something","ipa":"/ɪn tʃɑːrdʒ ʌv ˈsʌmθɪŋ riˈspɑːnsəbəl fɔːr ˈsʌmθɪŋ/","type":"phrase / pattern","meaning":"phụ trách/quản lí điều gì ~ chịu trách nhiệm về kết quả","definition":"Responsible for controlling something.","note":"in charge of nhấn mạnh quyền quản lí; responsible for nhấn mạnh nghĩa vụ và trách nhiệm về kết quả.","example":"Mai is in charge of the project and responsible for the final report."},{"number":234,"term":"assist ~ help · assistance · assistant","sourceTerm":"assist (v) ~ help (v) · assistance (n) · assistant (n)","spoken":"assist ~ help · assistance · assistant","ipa":"/əˈsɪst hɛlp əˈsɪstəns əˈsɪstənt/","type":"verb · noun","meaning":"giúp đỡ · sự giúp đỡ · người trợ giúp","definition":"To help; help that is given; a person who helps.","note":"assist trang trọng hơn help; assistance là danh từ không đếm được; assistant là người trợ giúp.","example":"The assistant helped and assisted the teacher, and her assistance saved time."},{"number":235,"term":"beg sb to do st","sourceTerm":"beg (v) sb to do st","spoken":"beg somebody to do something","ipa":"/bɛɡ ˈsʌˌmbɑːdi tuː duː ˈsʌmθɪŋ/","type":"verb","meaning":"nài nỉ ai đó làm gì","definition":"To ask someone very strongly.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: beg (v) sb to do st","example":"The child begged his mother to let him join the trip."},{"number":236,"term":"employ · employment >< unemployment · unemployed · employee · employer","sourceTerm":"employ (v) · employment (n) >< unemployment (n) · unemployed (a) · employee (n) · employer (n)","spoken":"employ · employment >< unemployment · unemployed · employee · employer","ipa":"/ɛˈmplɔɪ ɛˈmplɔɪmənt ˌʌnɪˈmplɔɪmənt ˌʌnɛˈmplɔɪd ɛˈmplɔɪi ɛˈmplɔɪɚ/","type":"verb · noun · adjective","meaning":"thuê/tuyển dụng · việc làm >< tình trạng thất nghiệp · thất nghiệp/không có việc · nhân viên · người sử dụng lao động","definition":"To give paid work; work; lack of work; a worker; a person or organization that provides paid work.","note":"employee là người lao động; employer là cá nhân hoặc tổ chức thuê lao động, không đồng nghĩa với owner.","example":"The employer employs twenty employees and provides stable employment while also training unemployed adults."},{"number":237,"term":"occupy · occupation ~ job","sourceTerm":"occupy (v) · occupation (n) ~ job (n)","spoken":"occupy · occupation ~ job","ipa":"/ˈɑːkjəˌpaɪ ˌɑːkjəˈpeɪʃən dʒɑːb/","type":"verb · noun","meaning":"chiếm chỗ hoặc thời gian · nghề nghiệp/công việc","definition":"To fill or use a space or period of time; a person's profession; a particular paid position.","note":"occupy là chiếm chỗ hoặc chiếm thời gian; occupation là nghề nghiệp và trang trọng hơn job.","example":"Teaching occupies most of her day; it is her occupation and her full-time job."},{"number":238,"term":"succeed in doing st · successful · success","sourceTerm":"succeed (v) in doing st · successful (a) · success (n)","spoken":"succeed in doing something · successful · success","ipa":"/səˈksiːd ɪn ˈduːɪŋ ˈsʌmθɪŋ səˈksɛsfəl səˈksɛs/","type":"verb · noun · adjective","meaning":"thành công trong việc gì · thành công/đạt kết quả tốt · sự thành công","definition":"To achieve the intended result; achieving good results; achievement.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: succeed (v) in doing st · successful (a) · success (n)","example":"Lan succeeded in passing the exam; her success made her a successful student."},{"number":239,"term":"responsible for st · responsibility","sourceTerm":"responsible (a) for st · responsibility (n)","spoken":"responsible for something · responsibility","ipa":"/riˈspɑːnsəbəl fɔːr ˈsʌmθɪŋ riˌspɑːnsəˈbɪləti/","type":"noun · adjective","meaning":"chịu trách nhiệm về điều gì · trách nhiệm","definition":"Having a duty for something; a duty.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: responsible (a) for st · responsibility (n)","example":"The leader is responsible for the plan and accepts this responsibility."},{"number":240,"term":"refer to sb/st","sourceTerm":"refer (v) to sb/st","spoken":"refer to somebody or something","ipa":"/rəˈfɝː tuː ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ/","type":"verb","meaning":"đề cập tới ai/cái gì","definition":"To mention or direct attention to someone or something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: refer (v) to sb/st","example":"The report refers to a recent study."},{"number":241,"term":"kind ~ type ~ sort · a kind/type/sort of st","sourceTerm":"kind (n) ~ type (n) ~ sort (n) · a kind/type/sort of st","spoken":"kind ~ type ~ sort · a kind or type or sort of something","ipa":"/kaɪnd taɪp sɔːrt ə kaɪnd ɔːr taɪp ɔːr sɔːrt ʌv ˈsʌmθɪŋ/","type":"noun","meaning":"loại/kiểu · một loại điều gì","definition":"A category or type.","note":"kind và sort tự nhiên trong giao tiếp; type thường dùng cho cách phân loại rõ ràng hoặc mang tính kĩ thuật.","example":"Teaching is a kind of work that needs patience; it is also a type or sort of public service."},{"number":242,"term":"call off ~ cancel","sourceTerm":"call off ~ cancel","spoken":"call off ~ cancel","ipa":"/kɔːl ɔːf ˈkænsəl/","type":"phrasal verb","meaning":"hủy bỏ","definition":"To cancel an event.","note":"call off là cụm động từ tự nhiên trong giao tiếp; cancel trung tính và dùng rộng hơn.","example":"The school called off and cancelled the match because of heavy rain."},{"number":243,"term":"put off ~ delay","sourceTerm":"put off ~ delay","spoken":"put off ~ delay","ipa":"/pʊt ɔːf dɪˈleɪ/","type":"phrasal verb","meaning":"chủ động hoãn lại ~ làm chậm/trì hoãn","definition":"To delay something.","note":"put off nghĩa là chủ động hoãn; delay nghĩa là làm chậm/diễn ra muộn, có thể không chủ ý.","example":"The team put off the meeting and delayed it until Friday."},{"number":244,"term":"take over ~ take control of","sourceTerm":"take over ~ take control of","spoken":"take over ~ take control of","ipa":"/teɪk ˈoʊvɚ teɪk kəˈntroʊl ʌv/","type":"phrasal verb","meaning":"tiếp quản/nắm quyền thay người khác ~ giành/nhận quyền kiểm soát","definition":"To gain control of an organization.","note":"take over nghĩa là tiếp quản/thay thế để nắm quyền; take control of chỉ hành động giành hoặc nhận quyền kiểm soát.","example":"A new manager took over the team and took control of the project."},{"number":245,"term":"set up ~ form ~ establish","sourceTerm":"set up ~ form ~ establish","spoken":"set up ~ form ~ establish","ipa":"/sɛt ʌp fɔːrm ɪˈstæblɪʃ/","type":"phrasal verb","meaning":"thành lập/thiết lập","definition":"To establish or create something.","note":"set up thông dụng; form nhấn mạnh tạo nhóm; establish trang trọng hơn và gợi sự tồn tại ổn định.","example":"The students set up a club, formed a small team, and established clear rules."}],"pronunciationFocus":[{"entryNumber":213,"points":[{"category":"word-stress","note":"apply nhấn âm cuối; application nhấn vào /ˈkeɪ/; scholarship nhấn âm đầu"}]},{"entryNumber":215,"points":[{"category":"silent-letter","note":"Phần -ue ở cuối colleague không được phát âm; từ kết thúc bằng /ɡ/"},{"category":"word-stress","note":"colleague nhấn âm đầu"}]},{"entryNumber":217,"points":[{"category":"common-error","note":"department bắt đầu bằng /dɪ/, còn apartment bắt đầu bằng /ə/; cả hai nhấn vào /ˈpɑːrt/"}]},{"entryNumber":223,"points":[{"category":"word-stress","note":"impress, impressive và impression đều nhấn âm tiết thứ hai"},{"category":"linking","note":"Trong make‿an impression, nối /k/ cuối make sang nguyên âm /æ/ của an"}]},{"entryNumber":229,"points":[{"category":"final-sound","note":"tax kết thúc bằng cụm /ks/; giữ đủ cả hai phụ âm"}]},{"entryNumber":230,"points":[{"category":"final-sound","note":"wealth kết thúc bằng cụm /lθ/; wealthy giữ /lθ/ trước âm /i/"}]},{"entryNumber":236,"points":[{"category":"word-stress","note":"employ, employment, employee và employer đều giữ trọng âm chính ở âm tiết thứ hai"}]},{"entryNumber":245,"points":[{"category":"linking","note":"Trong set‿up, nối /t/ cuối set sang nguyên âm /ʌ/ của up"}]}]}};
